        chosen.append(items[index][2])
    return cost, len(chosen), chosen


def _exhaustive_cover(items, full):
    """Exact fallback: enumerate every subset of the candidate queries."""
    count = len(items)
    size = 1 << count
    unions = array('I', bytes(4 * size))
    costs = array('H', bytes(2 * size))
    best_cost = None
    best_count = None
    best_mask = 0
    for mask in range(size):
        if mask:
            low = mask & -mask
            index = low.bit_length() - 1
            previous = mask ^ low
            union = unions[previous] | items[index][0]
            unions[mask] = union
            value = costs[previous] + items[index][1]
            costs[mask] = value
        else:
            union = 0
            value = 0
        if union == full:
            length = mask.bit_count()
            if best_cost is None or (value, length) < (best_cost, best_count):
                best_cost = value
                best_count = length
                best_mask = mask
    chosen = [items[index][2] for index in range(count)
              if (best_mask >> index) & 1]
    return best_cost, best_count, chosen


def _solve_cover(items, full, pair_count):
    """Exact minimum cost (then minimum count) set cover."""
    if not items:
        return None
    # Drop dominated candidates: a superset mask at no higher cost is always
    # at least as good and uses the same number of queries.
    order = sorted(range(len(items)),
                   key=lambda i: (items[i][1], -bin(items[i][0]).count('1'), i))
    kept = []
    for index in order:
        mask = items[index][0]
        if any((mask & ~items[other][0]) == 0 for other in kept):
            continue
        kept.append(index)
    items = [items[index] for index in kept]

    elem_items = [[] for _ in range(pair_count)]
    conflict = [0] * pair_count
    items = [(mask & full, cost, qid) for mask, cost, qid in items]
    for index, (mask, _cost, _qid) in enumerate(items):
        bits = mask
        while bits:
            low = bits & -bits
            element = low.bit_length() - 1
            elem_items[element].append(index)
            conflict[element] |= mask
            bits ^= low
    min_cost = []
    for element in range(pair_count):
        options = elem_items[element]
        if not options:
            return None
        min_cost.append(min(items[index][1] for index in options))
    element_order = sorted(range(pair_count),
                            key=lambda element: (-min_cost[element], element))

    best = [None, None, None]
    greedy = _greedy_cover(items, full, pair_count)
    if greedy is not None:
        best[0], best[1], best[2] = greedy[0], greedy[1], list(greedy[2])
    seen = {}
    budget = [400000]

    def search(covered, cost, count, chosen):
        budget[0] -= 1
        if budget[0] < 0:
            raise _Budget()
        if covered == full:
            if best[0] is None or (cost, count) < (best[0], best[1]):
                best[0] = cost
                best[1] = count
                best[2] = list(chosen)
            return
        previous = seen.get(covered)
        if previous is not None and (cost, count) >= previous:
            return
        seen[covered] = (cost, count)
        bound = _pack_bound(element_order, conflict, min_cost, covered,
                            pair_count)
        if best[0] is not None:
            if cost + bound > best[0]:
                return
            if cost + bound == best[0] and count + 1 >= best[1]:
                return
        target = None
        options = None
        for element in range(pair_count):
            if (covered >> element) & 1:
                continue
            available = elem_items[element]
            if not available:
                continue
            if options is None or len(available) < len(options):
                target = element
                options = available
        if options is None:
            return
        for index in sorted(options, key=lambda i: (items[i][1], items[i][2])):
            mask, item_cost, qid = items[index]
            chosen.append(qid)
            search(covered | mask, cost + item_cost, count + 1, chosen)
            chosen.pop()

    try:
        search(0, 0, 0, [])
    except _Budget:
        fallback = _exhaustive_cover(items, full)
        if fallback is not None:
            best[0], best[1], best[2] = fallback[0], fallback[1], fallback[2]
    if best[0] is None:
        return None
    return best[0], best[1], best[2]


